export function docCloseArgv(opts: { doc?: string; id?: string; pid?: number; unsaved?: string; out?: string; release?: string; requestId?: string; expectSession?: string; expectDoc?: string; wait?: boolean; noWait?: boolean; timeoutSeconds?: number; } = {}): string[] {
  const argv = ["doc", "close"];
  option(argv, "--doc", opts.doc);
  option(argv, "--id", opts.id);
  option(argv, "--pid", opts.pid);
  option(argv, "--unsaved", opts.unsaved);
  option(argv, "--out", opts.out);
  option(argv, "--release", opts.release);
  option(argv, "--request-id", opts.requestId);
  option(argv, "--expect-session", opts.expectSession);
  option(argv, "--expect-doc", opts.expectDoc);
  if (opts.wait) argv.push("--wait");
  if (opts.noWait) argv.push("--no-wait");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  argv.push("--json");
  return argv;
}

export function docListArgv(opts: { id?: string; pid?: number; doc?: string; borrows?: boolean; recent?: boolean; cloud?: boolean; hub?: string; project?: string; folder?: string; year?: string; } = {}): string[] {
  const argv = ["doc", "list"];
  option(argv, "--id", opts.id);
  option(argv, "--pid", opts.pid);
  option(argv, "--doc", opts.doc);
  if (opts.borrows) argv.push("--borrows");
  if (opts.recent) argv.push("--recent");
  if (opts.cloud) argv.push("--cloud");
  option(argv, "--hub", opts.hub);
  option(argv, "--project", opts.project);
  option(argv, "--folder", opts.folder);
  option(argv, "--year", opts.year);
  argv.push("--json");
  return argv;
}

export function docOpenArgv(opts: { source?: string; id?: string; pid?: number; template?: string; detach?: boolean; window?: string; upgrade?: boolean; conflict?: string; links?: string; reload?: boolean; start?: boolean; year?: string; requestId?: string; expectSession?: string; expectDoc?: string; wait?: boolean; noWait?: boolean; timeoutSeconds?: number; } = {}): string[] {
  const argv = ["doc", "open"];
  if (opts.source != null) argv.push(String(opts.source).trim());
  option(argv, "--id", opts.id);
  option(argv, "--pid", opts.pid);
  option(argv, "--template", opts.template);
  if (opts.detach) argv.push("--detach");
  option(argv, "--window", opts.window);
  if (opts.upgrade) argv.push("--upgrade");
  option(argv, "--conflict", opts.conflict);
  option(argv, "--links", opts.links);
  if (opts.reload) argv.push("--reload");
  if (opts.start) argv.push("--start");
  option(argv, "--year", opts.year);
  option(argv, "--request-id", opts.requestId);
  option(argv, "--expect-session", opts.expectSession);
  option(argv, "--expect-doc", opts.expectDoc);
  if (opts.wait) argv.push("--wait");
  if (opts.noWait) argv.push("--no-wait");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  argv.push("--json");
  return argv;
}

